local emotions = require "wa.emotions"
local variables = require "wa.variables"

local R = require "core.lib.rathena"
local ACCOUNT_KAFRA_CODE = variables.account_integer "kafra_code"

return function(player, conversation, npc, ...)
  local npc_name, comp_name, code = "", "", 0
  local sub_s_set
  sub_s_set = function(player, conversation, npc, ...)
    local npc_name, comp_name, code = "", "", 0
    local args = table.pack(...)
    ::s_set::
    npc_name = R.text(R.arg(args, 0))
    comp_name = R.text(R.arg(args, 1))
    conversation:say(npc_name, "Now enter your ^FF0000new password^000000 to protect your storage from thieves.")
    code = (require("core.functions.F_EntKafCode")(player, conversation, npc) or 0)
    if (not (code ~= 0)) then
      conversation:say("The password hasn't been changed.")
      npc:show_emotion(emotions.scratch)
      do return end
    end
    conversation:wait_for_next()
    conversation:say(npc_name)
    if (player.zeny < 5000) then
      conversation:say("You don't have enough zeny.")
      npc:show_emotion(emotions.money)
      do return end
    end
    player:pay_zeny(5000)
    ACCOUNT_KAFRA_CODE:set(player, code)
    conversation:say("You've protected your storage with a secret password.", "Thank you for using " .. comp_name .. ".")
    npc:show_emotion(emotions.thanks)
    do return end
  end
  local args = table.pack(...)
  npc_name = R.text(R.arg(args, 0))
  comp_name = R.text(R.arg(args, 1))
  conversation:say(npc_name)
  if (ACCOUNT_KAFRA_CODE:get(player) == 0) then
    conversation:say("" .. comp_name .. " proudly presents you a new service:", "Additional storage protection with a password.")
    conversation:wait_for_next()
    if (conversation:choose("Set new password -> 5000z", "Cancel") == 1) then
      sub_s_set(player, conversation, npc, npc_name, comp_name)
    end
    conversation:hide_image()
    R.stop()
  end
  conversation:say("Your storage is protected with a password. What would you do now?")
  conversation:wait_for_next()
  do
    local value_1 = conversation:choose("Change old password -> 5000z", "Remove storage password -> 1000z", "Cancel")
    if value_1 == 1 then goto case_3
    elseif value_1 == 2 then goto case_4
    elseif value_1 == 3 then goto case_5
    end
    goto switch_end_2
    ::case_3::
    conversation:say(npc_name, "At first, please enter your ^0000FFold password^000000.")
    code = (require("core.functions.F_EntKafCode")(player, conversation, npc) or 0)
    if ((not (code ~= 0)) or (code ~= ACCOUNT_KAFRA_CODE:get(player))) then
      conversation:say("Wrong password. You can't set a new password.")
      npc:show_emotion(emotions.scratch)
      goto switch_end_2
    end
    conversation:wait_for_next()
    sub_s_set(player, conversation, npc, npc_name, comp_name)
    goto switch_end_2
    ::case_4::
    conversation:say(npc_name, "Please, enter your password before its removal.")
    code = (require("core.functions.F_EntKafCode")(player, conversation, npc) or 0)
    if (not (code ~= 0)) then
      conversation:say("The password hasn't been removed.")
      npc:show_emotion(emotions.scratch)
      goto switch_end_2
    end
    conversation:wait_for_next()
    conversation:say(npc_name)
    if (player.zeny < 1000) then
      conversation:say("You don't have enough zeny.")
      npc:show_emotion(emotions.money)
      goto switch_end_2
    end
    player:pay_zeny(1000)
    if (code == ACCOUNT_KAFRA_CODE:get(player)) then
      ACCOUNT_KAFRA_CODE:set(player, 0)
      conversation:say("You've successfully cleared your storage password.", "Thank you for using " .. comp_name .. ".")
      npc:show_emotion(emotions.thanks)
    else
      conversation:say("Wrong password. We won't return your 1000z.", "Please, next time enter correct password.")
      npc:show_emotion(emotions.sorry)
    end
    goto switch_end_2
    ::case_5::
    goto switch_end_2
    ::switch_end_2::
  end
  conversation:hide_image()
  R.stop()
end
